"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[9075],{6746(e){e.exports=JSON.parse('{"tag":{"label":"Big-O","permalink":"/concepts/tags/big-o","allTagsPath":"/concepts/tags","count":3,"items":[{"id":"foundations-of-algorithms/asymptotic-notation","title":"Asymptotic Notation","description":"In the previous section, we calculated the exact polynomial execution time of a function, such as $T(n) = 3n + 4$. While mathematically precise, dealing with exact polynomials becomes impossible as software architectures grow to millions of lines of code.","permalink":"/concepts/foundations-of-algorithms/asymptotic-notation"},{"id":"foundations-of-algorithms/case-study-pairwise","title":"Case Study - Pairwise Product","description":"To truly understand why algorithmics matters, it helps to experience failure first. In this case study we take a deceptively simple problem and solve it again and again. Each version fixes a problem of the previous one, and each fix teaches a different lesson: about the limits of data types, the cost of naive strategies, the impact of data representation, and the danger of \\"optimisations\\" that are not actually correct.","permalink":"/concepts/foundations-of-algorithms/case-study-pairwise"},{"id":"foundations-of-algorithms/searching-case-studies","title":"Searching Case Studies","description":"We have established the mathematical foundations of complexity analysis and asymptotic notation. Now, we will apply these engineering principles to one of the most fundamental operations in computer science: Information Retrieval (Searching).","permalink":"/concepts/foundations-of-algorithms/searching-case-studies"}],"unlisted":false}}')}}]);